import { describe, it, expect } from "vitest";
import { nextGeneration } from "./game-of-life.js";

describe("Game of Life - nextGeneration", () => {
  it.todo("returns an empty grid for an empty grid — [] → []");

  it.todo(
    "Rule 1 (underpopulation): a single live cell with 0 neighbors dies — [(0,0)] → []",
  );

  it.todo(
    "Rule 1 (underpopulation): two adjacent live cells each with 1 neighbor die — [(0,1), (1,1)] → []",
  );

  it.todo(
    "Rule 2 (survival): a live cell with 2 live neighbors lives on — blinker [(0,0), (0,1), (0,2)] keeps (0,1) alive",
  );

  it.todo(
    "Rule 2 (survival): a live cell with 3 live neighbors lives on — [(0,0), (1,0), (2,0), (1,2)] keeps (1,1)... center survives per spec example ### / ... / .#. → .#. / .#. / ...",
  );

  it.todo(
    "Rule 3 (overpopulation): a live cell with 4 live neighbors dies — ### / .#. / ### → #.# / #.# / #.#",
  );

  it.todo(
    "Rule 4 (reproduction): a dead cell with exactly 3 live neighbors becomes alive — ##. / #.. / ... → ##. / ##. / ...",
  );

  it.todo(
    "handles negative coordinates — blinker [(0,0), (0,1), (0,2)] → [(-1,1), (0,1), (1,1)]",
  );

  it.todo(
    "block still life stays unchanged — [(0,0), (1,0), (0,1), (1,1)] → same four cells",
  );

  it.todo(
    "blinker oscillates back to vertical after two generations — [(-1,1), (0,1), (1,1)] → [(0,0), (0,1), (0,2)]",
  );
});

