1	export type Cell = [x: number, y: number];
2	
3	const isSameCell = ([x, y]: Cell, [otherX, otherY]: Cell): boolean =>
4	  x === otherX && y === otherY;
5	
6	const isNeighborOf = (cell: Cell, candidate: Cell): boolean => {
7	  const [x, y] = cell;
8	  const [candidateX, candidateY] = candidate;
9	  const isTouching =
10	    Math.abs(candidateX - x) <= 1 && Math.abs(candidateY - y) <= 1;
11	  return isTouching && !isSameCell(cell, candidate);
12	};
13	
14	const countLiveNeighbors = (cell: Cell, liveCells: Cell[]): number =>
15	  liveCells.filter((candidate) => isNeighborOf(cell, candidate)).length;
16	
17	export function nextGeneration(liveCells: Cell[]): Cell[] {
18	  return liveCells.filter((cell) => countLiveNeighbors(cell, liveCells) === 2);
19	}

