export type Cell = [x: number, y: number];

const isSameCell = ([x, y]: Cell, [otherX, otherY]: Cell): boolean =>
  x === otherX && y === otherY;

const areNeighbors = (cell: Cell, other: Cell): boolean => {
  const [x, y] = cell;
  const [otherX, otherY] = other;
  const isTouching = Math.abs(otherX - x) <= 1 && Math.abs(otherY - y) <= 1;
  return isTouching && !isSameCell(cell, other);
};

const countLiveNeighbors = (cell: Cell, liveCells: Cell[]): number =>
  liveCells.filter((liveCell) => areNeighbors(cell, liveCell)).length;

// Fewer than 2 neighbors is underpopulation, more than 3 is overpopulation;
// both are death. Only this band survives.
const MIN_NEIGHBORS_TO_SURVIVE = 2;
const MAX_NEIGHBORS_TO_SURVIVE = 3;

const survives = (liveNeighborCount: number): boolean =>
  liveNeighborCount >= MIN_NEIGHBORS_TO_SURVIVE &&
  liveNeighborCount <= MAX_NEIGHBORS_TO_SURVIVE;

export function nextGeneration(liveCells: Cell[]): Cell[] {
  return liveCells.filter((cell) =>
    survives(countLiveNeighbors(cell, liveCells)),
  );
}

